package mod.cdv.tnpc.tactical;
import fixture.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.EquipmentSlot;import net.minecraft.world.item.ItemStack;import mod.cdv.tnpc.entity.AutoGunOperator;
public final class Social21Checks {
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static final class Event {Object n,p;boolean canceled;Object result;Event(Object n,Object p){this.n=n;this.p=p;}public Object getTarget(){return n;}public Object getEntity(){return p;}public Object getHand(){return net.minecraft.world.InteractionHand.MAIN_HAND;}public void setCanceled(boolean b){canceled=b;}public void setCancellationResult(Object r){result=r;}}
 public static final class Mouse {public boolean canceled;int button,action;Mouse(int b,int a){button=b;action=a;}public int getButton(){return button;}public int getAction(){return action;}public void setCanceled(boolean b){canceled=b;}}
 public static void main(String[] args)throws Exception{
 for(int kind=0;kind<3;kind++)for(boolean armed:new boolean[]{false,true})for(boolean faction:new boolean[]{false,true})ok(SocialRules.attack(kind,armed,faction,true,-100,-100,0),"self defense bypasses pacifism, fear, weapon and membership gates");
 World w=new World();AutoGunOperator n=SocialChecks.npc(w,1);Player p=new Player(w);p.x=4;n.tag.putInt("soc_persona",2);
 for(String item:new String[]{"tacz:gun","lrtactical:melee","firstaid:bandage","lrtactical:bandage"}){p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(item,2));Event e=new Event(n,p);Interaction21.entity(e);ok(e.canceled&&e.result!=null&&Conversation.SESSIONS.containsKey(p),"held item cannot steal entity interaction: "+item);ok(p.getMainHandItem().count==2,"conversation never consumes held item");}
 net.minecraft.client.Minecraft mc=net.minecraft.client.Minecraft.getInstance();mc.player=p;mc.hitResult=new net.minecraft.world.phys.EntityHitResult(n);Mouse mouse=new Mouse(1,1);Interaction21.mouse(mouse);ok(mouse.canceled&&mc.gameMode.uses==1,"raw mouse use reaches conversation before melee heavy attack");Mouse attack=new Mouse(0,1);Interaction21.mouse(attack);ok(!attack.canceled&&mc.gameMode.uses==1,"normal attack input preserved");mc.screen=new Object();Mouse gui=new Mouse(1,1);Interaction21.mouse(gui);ok(!gui.canceled,"GUI clicks are not intercepted");mc.screen=null;mc.hitResult=new Object();Mouse air=new Mouse(1,1);Interaction21.mouse(air);ok(!air.canceled,"aim and item use away from NPC preserved");mc.hitResult=new net.minecraft.world.phys.EntityHitResult(n);mc.options.keyUse.button=2;Mouse rebind=new Mouse(2,1);Interaction21.mouse(rebind);ok(rebind.canceled&&mc.gameMode.uses==2,"remapped use mouse button supported");Mouse release=new Mouse(2,0);Interaction21.mouse(release);ok(!release.canceled,"release events preserved");
 Social.Memory m=Social.mem(n);ok(Conversation.focus(n,m,0)&&m.occupied&&n.navigation.moves>0,"NPC approaches interlocutor");p.x=2;int stops=n.navigation.stops;ok(Conversation.focus(n,m,0)&&n.navigation.stops>stops,"NPC stays near interlocutor");Conversation.action(p,"close");ok(!Conversation.focus(n,m,0),"closing releases conversation");
 AutoGunOperator witness=SocialChecks.npc(w,2);witness.x=3;NpcMedicine.init(n);Social.hurt(n,new SocialChecks.Source(p),1,true);ok(Social.enemy(n,p)&&Social.enemy(witness,p),"victim and visible peaceful witness remember aggressor");SocialChecks.acquire(witness,10);ok(witness.target==p,"peaceful witness retaliates rather than empty threats");w.now=20;Conversation.interact(n,p,net.minecraft.world.InteractionHand.MAIN_HAND);ok(Conversation.action(p,"apologize")==1,"aggressor can offer apology");int trust=Social.trust(n,p);w.now+=10;ok(Conversation.action(p,"apologize")==0&&Social.trust(n,p)==trust,"apology cannot be spammed");w.now+=1200;Conversation.interact(n,p,net.minecraft.world.InteractionHand.MAIN_HAND);Conversation.action(p,"apologize");w.now+=1200;Conversation.interact(n,p,net.minecraft.world.InteractionHand.MAIN_HAND);Conversation.action(p,"apologize");ok(!Social.enemy(n,p)&&Social.trust(n,p)>=0,"earned reconciliation clears personal retaliation");
 SocialChecks.faction(w,p,n);Social.hurt(n,new SocialChecks.Source(p),1,true);ok(Boolean.FALSE.equals(Social.allied(n,p)),"betrayal overrides native faction protection");
 World client=new World();client.client=true;client.server=null;AutoGunOperator ghost=new AutoGunOperator(client);Social.death(ghost,new SocialChecks.Source(p));Social.hurt(ghost,new SocialChecks.Source(p),1,true);ok(!ghost.tag.getBoolean("np15_parts"),"client callbacks do not touch server ledger or medicine");
 System.out.println("NPC_INTERACTION_DEFENSE_RECONCILIATION_CHECKS="+checks);
 }
}
